-- handwritten: runtime/client/mixins/Cam.lua

do

local CreateCamWithParams, SetCamActive, RenderScriptCams, DestroyCam, SetCamActiveWithInterp =
  CreateCamWithParams, SetCamActive, RenderScriptCams, DestroyCam, SetCamActiveWithInterp
local IsCamRendering = IsCamRendering

---@param o fx.CamCreateOptions
---@return fx.Cam?
statics.create = function(o)
  local c, r = o.coords, o.rot
  local h = CreateCamWithParams(o.name or "DEFAULT_SCRIPTED_CAMERA", c.x + 0.0, c.y + 0.0, c.z + 0.0,
    r and r.x + 0.0 or 0.0, r and r.y + 0.0 or 0.0, r and r.z + 0.0 or 0.0, (o.fov or 50.0) + 0.0, false, o.rotationOrder or 2)
  -- rotation order 2 (YXZ) is what the game scripts use; 0 is a valid camera handle
  local cam = T.wrap(h)
  if cam and o.render ~= false then cam:render(true, o.ease, o.easeTime) end
  return cam
end

-- a scripted camera shows nothing until RENDER_SCRIPT_CAMS(true)
---@param self fx.Cam
---@param on? boolean
---@param ease? boolean
---@param easeTime? integer
---@return fx.Cam
methods.render = function(self, on, ease, easeTime)
  on = on ~= false
  if on then SetCamActive(self.handle, true) end
  RenderScriptCams(on, ease or false, easeTime or 0, true, false)
  if not on then SetCamActive(self.handle, false) end
  return self
end

---@param self fx.Cam
---@param to fx.Cam
---@param duration? integer
---@param easeLocation? integer
---@param easeRotation? integer
---@return fx.Cam
methods.blendTo = function(self, to, duration, easeLocation, easeRotation)
  SetCamActiveWithInterp(rt.toHandle(to), self.handle, duration or 1000, easeLocation or 1, easeRotation or 1)
  return to
end

---@param self fx.Cam
---@param ease? boolean
---@param easeTime? integer
---@return nil
methods.destroy = function(self, ease, easeTime)
  -- only when this camera is on screen: another one (a blend target, another resource's) keeps rendering
  if IsCamRendering(self.handle) then RenderScriptCams(false, ease or false, easeTime or 0, true, false) end
  DestroyCam(self.handle, false)
  rt.forget(self)
  return nil
end

local DoScreenFadeOut, DoScreenFadeIn, IsScreenFadedOut, IsScreenFadedIn =
  DoScreenFadeOut, DoScreenFadeIn, IsScreenFadedOut, IsScreenFadedIn

---@param label string
---@param duration any
---@return integer
local function fadeDuration(label, duration)
  if duration == nil then return 500 end
  if math.type(duration) ~= "integer" or duration < 0 then error(label .. ": duration must be a positive integer (ms)", 3) end
  return duration
end

---@param duration? integer
---@return fx.Promise
statics.fadeOutAsync = function(duration)
  local ms = fadeDuration("Cam.fadeOutAsync", duration)
  DoScreenFadeOut(ms)
  return rt.waitUntil("Cam.fadeOutAsync", IsScreenFadedOut, ms + rt.DEFAULT_TIMEOUT)
end

---@param duration? integer
---@return fx.Promise
statics.fadeInAsync = function(duration)
  local ms = fadeDuration("Cam.fadeInAsync", duration)
  DoScreenFadeIn(ms)
  return rt.waitUntil("Cam.fadeInAsync", IsScreenFadedIn, ms + rt.DEFAULT_TIMEOUT)
end

end

return rt.finalize(T)
